DROP TABLE IF EXISTS `journal_deadlines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `journal_deadlines` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `internship_id` bigint(20) unsigned NOT NULL,
  `week_number` int(10) unsigned NOT NULL,
  `due_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `set_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `journal_deadlines_internship_week_unique` (`internship_id`,`week_number`),
  KEY `journal_deadlines_set_by_foreign` (`set_by`),
  CONSTRAINT `journal_deadlines_internship_id_foreign` FOREIGN KEY (`internship_id`) REFERENCES `internships` (`id`) ON DELETE CASCADE,
  CONSTRAINT `journal_deadlines_set_by_foreign` FOREIGN KEY (`set_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `journal_deadlines` WRITE;
/*!40000 ALTER TABLE `journal_deadlines` DISABLE KEYS */;
/*!40000 ALTER TABLE `journal_deadlines` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `journal_entries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `journal_entries` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `internship_id` bigint(20) unsigned NOT NULL,
  `entry_number` int(10) unsigned NOT NULL,
  `week_number` int(10) unsigned DEFAULT NULL,
  `date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `activities_summary` text DEFAULT NULL,
  `learnings` text DEFAULT NULL COMMENT 'What the student learned',
  `challenges` text DEFAULT NULL,
  `status` enum('draft','submitted','approved','needs_revision','rejected','supervisor_note') NOT NULL DEFAULT 'draft',
  `submitted_at` timestamp NULL DEFAULT NULL,
  `deadline_at` timestamp NULL DEFAULT NULL,
  `submitted_late` tinyint(1) NOT NULL DEFAULT 0,
  `score` int(11) DEFAULT NULL,
  `file_path` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `supervisor_feedback` text DEFAULT NULL,
  `supervisor_reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `supervisor_reviewed_at` timestamp NULL DEFAULT NULL,
  `faculty_feedback` text DEFAULT NULL,
  `faculty_reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `faculty_reviewed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `journal_entries_internship_week_unique` (`internship_id`,`week_number`),
  KEY `journal_entries_supervisor_reviewed_by_foreign` (`supervisor_reviewed_by`),
  KEY `journal_entries_faculty_reviewed_by_foreign` (`faculty_reviewed_by`),
  KEY `journal_entries_internship_id_date_index` (`internship_id`,`date`),
  KEY `journal_entries_status_index` (`status`),
  KEY `journal_entries_internship_id_week_index` (`internship_id`,`week_number`)
) ENGINE=InnoDB AUTO_INCREMENT=409 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `journal_entries` WRITE;
/*!40000 ALTER TABLE `journal_entries` DISABLE KEYS */;
INSERT INTO `journal_entries` VALUES (50,13,1,1,'2026-08-10','2026-08-16','Assisted in reviewing and updating internal system documentation for the client-facing web portal.','Learned how to structure technical documentation so both developers and non-technical staff can follow it.','Some legacy modules had no prior documentation, requiring code tracing before writing anything down.','approved','2026-08-16 16:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'Good progress this week — keep documenting specific tools and outcomes.',21,'2026-08-17 16:00:00','2026-09-24 08:07:58','2026-09-24 08:07:58',NULL),(51,13,2,2,'2026-08-17','2026-08-23','Performed data validation checks on migrated customer records against the source database.','Gained hands-on experience with SQL queries used to spot mismatched or duplicate records.','Encountered inconsistent date formats across regions that required a custom normalization script.','approved','2026-08-23 16:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'Good progress this week — keep documenting specific tools and outcomes.',21,'2026-08-24 16:00:00','2026-09-24 08:07:58','2026-09-24 08:07:58',NULL),(52,13,3,3,'2026-08-24','2026-08-30','Executed manual and scripted software testing on a new feature release before staging deployment.','Understood the difference between smoke testing and full regression testing in a real release cycle.','Reproducing an intermittent UI bug took several attempts across different browsers.','approved','2026-08-30 16:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'Good progress this week — keep documenting specific tools and outcomes.',21,'2026-08-31 16:00:00','2026-09-24 08:07:58','2026-09-24 08:07:58',NULL),(53,13,4,4,'2026-08-31','2026-09-06','Checked database integrity constraints and indexed slow-running queries flagged by the monitoring dashboard.','Learned to read query execution plans to identify missing indexes.','Balancing index additions against write-performance tradeoffs was new territory.','approved','2026-09-06 16:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'Good progress this week — keep documenting specific tools and outcomes.',21,'2026-09-07 16:00:00','2026-09-24 08:07:58','2026-09-24 08:07:58',NULL),(54,13,5,5,'2026-09-07','2026-09-13','Handled Tier-1 helpdesk tickets, troubleshooting login and VPN connectivity issues for end users.','Improved communication skills explaining technical fixes to non-technical staff over chat and calls.','A recurring VPN drop issue needed escalation after initial troubleshooting steps failed.','approved','2026-09-13 16:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'Good progress this week — keep documenting specific tools and outcomes.',21,'2026-09-14 16:00:00','2026-09-24 08:07:58','2026-09-24 08:07:58',NULL),(55,13,6,6,'2026-09-14','2026-09-20','Prepared a weekly status report summarizing ticket volume, resolution time, and open issues for the team lead.','Learned how operational metrics are compiled and presented to stakeholders.','Reconciling numbers from two different ticketing exports took longer than expected.','submitted','2026-09-20 16:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-24 08:07:58','2026-09-24 08:07:58',NULL),(57,36,1,1,'2026-08-24','2026-08-30','Assisted in reviewing and updating internal system documentation for the client-facing web portal.','Learned how to structure technical documentation so both developers and non-technical staff can follow it.','Some legacy modules had no prior documentation, requiring code tracing before writing anything down.','approved','2026-08-30 16:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,'Good progress this week — keep documenting specific tools and outcomes.',14,'2026-08-31 16:00:00','2026-09-24 08:07:58','2026-09-24 08:07:58',NULL),(58,36,2,2,'2026-08-31','2026-09-06','Performed data validation checks on migrated customer records against the source database.','Gained hands-on experience with SQL queries used to spot mismatched or duplicate records.