INSERT INTO `student_portfolios` VALUES (1,9,25,'Host Establishment',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{\"acknowledgement\":null,\"teachers_prayer\":\"Lord, I pray that you would give me a heart that is completely devoted to You and to the students You have placed in my care...\\n\\n(Edit to add your personal 4-stanza prayer)\",\"teachers_creed\":\"I Commit to My Students:\\n...\\n\\nI Commit to Excellence in Teaching:\\n...\\n\\nI Commit to Partnership:\\n...\\n\\nI Commit to Myself as an Educator:\\n...\",\"teaching_philosophy\":null,\"why_teaching\":null,\"beliefs_about_learners\":null,\"goals_as_teacher\":null,\"cooperating_school_history\":null,\"deped_vision_mission\":\"DepEd Vision:\\nWe dream of Filipinos who passionately love their country and whose values and competencies enable them to realize their full potential and contribute meaningfully to building the nation.\\n\\nDepEd Mission:\\nTo protect and promote the right of every Filipino to quality, equitable, culture-based, and complete basic education where:...\",\"school_vision_mission\":null,\"school_programs\":null,\"learner_population\":null,\"observation_logs\":null,\"classroom_management\":null,\"teaching_environment\":null,\"culminating_reflection\":null,\"strengths_discovered\":null,\"areas_for_improvement\":null,\"ready_for_profession\":null,\"narrative_observation\":null,\"narrative_assisted\":null,\"narrative_independent\":null,\"narrative_final_demo\":null,\"highlight_growth\":null}','2026-09-05 00:28:40','2026-09-05 00:28:40'),(5,13,22,'Oracle Philippines','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','Oracle Philippines has operated in the Philippines for over a decade, supporting global clients from a local delivery team.',NULL,'So far, Christian Hero has been building skills in documentation, testing, data validation, and helpdesk support; a full reflection will be completed once the internship concludes.',NULL,NULL,NULL,NULL,NULL,'2026-09-24 08:07:58','2026-09-24 22:58:49'),(6,36,104,'IBM Philippines','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','IBM Philippines has operated in the Philippines for over a decade, supporting global clients from a local delivery team.',NULL,'So far, Lara has been building skills in documentation, testing, data validation, and helpdesk support; a full reflection will be completed once the internship concludes.',NULL,NULL,NULL,NULL,NULL,'2026-09-24 08:07:58','2026-09-24 22:58:49'),(7,37,105,'DXC Technology Philippines','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','DXC Technology Philippines has operated in the Philippines for over a decade, supporting global clients from a local delivery team.',NULL,'So far, Max has been building skills in documentation, testing, data validation, and helpdesk support; a full reflection will be completed once the internship concludes.',NULL,NULL,NULL,NULL,NULL,'2026-09-24 08:07:58','2026-09-24 22:58:49'),(30,62,24,'Infor','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','Infor has operated in the Philippines for over a decade, growing a local delivery team that supports global clients across software development, quality assurance, and IT support.','The organization maintained clear data-privacy and client-confidentiality practices, which Clarence was required to acknowledge and follow from day one.','Clarence developed practical skills in documentation, testing, data validation, and helpdesk support, alongside stronger habits around time management and professional communication.','The internship offered exposure to real production systems and cross-functional teams, giving Clarence a realistic view of day-to-day IT operations work.','Work was reviewed against the company\'s existing QA and documentation standards, requiring Clarence to adapt to formal review cycles.','Future interns would benefit from an earlier walkthrough of the ticketing and version-control tools used by the team.','Ask questions early, keep a personal log of daily tasks, and treat every ticket as a chance to learn the underlying system.',NULL,'2026-09-24 08:54:46','2026-09-24 08:54:46'),(31,63,23,'Accenture Philippines','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','Accenture Philippines has operated in the Philippines for over a decade, growing a local delivery team that supports global clients across software development, quality assurance, and IT support.','The organization maintained clear data-privacy and client-confidentiality practices, which Angel Luis was required to acknowledge and follow from day one.','Angel Luis developed practical skills in documentation, testing, data validation, and helpdesk support, alongside stronger habits around time management and professional communication.','The internship offered exposure to real production systems and cross-functional teams, giving Angel Luis a realistic view of day-to-day IT operations work.','Work was reviewed against the company\'s existing QA and documentation standards, requiring Angel Luis to adapt to formal review cycles.','Future interns would benefit from an earlier walkthrough of the ticketing and version-control tools used by the team.','Ask questions early, keep a personal log of daily tasks, and treat every ticket as a chance to learn the underlying system.',NULL,'2026-09-24 08:54:46','2026-09-24 08:54:46'),(32,64,103,'Microsoft Philippines','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','Microsoft Philippines has operated in the Philippines for over a decade, growing a local delivery team that supports global clients across software development, quality assurance, and IT support.','The organization maintained clear data-privacy and client-confidentiality practices, which Arthur was required to acknowledge and follow from day one.','Arthur developed practical skills in documentation, testing, data validation, and helpdesk support, alongside stronger habits around time management and professional communication.','The internship offered exposure to real production systems and cross-functional teams, giving Arthur a realistic view of day-to-day IT operations work.','Work was reviewed against the company\'s existing QA and documentation standards, requiring Arthur to adapt to formal review cycles.','Future interns would benefit from an earlier walkthrough of the ticketing and version-control tools used by the team.','Ask questions early, keep a personal log of daily tasks, and treat every ticket as a chance to learn the underlying system.',NULL,'2026-09-24 08:54:46','2026-09-24 08:54:46'),(33,65,110,'Cognizant Philippines','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','Cognizant Philippines has operated in the Philippines for over a decade, growing a local delivery team that supports global clients across software development, quality assurance, and IT support.','The organization maintained clear data-privacy and client-confidentiality practices, which Terrence John was required to acknowledge and follow from day one.','Terrence John developed practical skills in software testing, API test automation, debugging, database maintenance, and code review, alongside stronger habits around time management and professional communication.','The internship offered exposure to real production systems and cross-functional teams, giving Terrence John a realistic view of day-to-day IT operations work.','Work was reviewed against the company\'s existing QA and documentation standards, requiring Terrence John to adapt to formal review cycles.','Future interns would benefit from an earlier walkthrough of the ticketing and version-control tools used by the team.','Ask questions early, keep a personal log of daily tasks, and treat every ticket as a chance to learn the underlying system.',NULL,'2026-09-24 22:58:49','2026-09-24 22:58:49'),(34,66,111,'NTT DATA Philippines','Metro Manila, Philippines','To be the technology partner of choice for organizations transforming their digital operations.','To deliver reliable, innovative software and IT services that help clients and communities thrive.','NTT DATA Philippines has operated in the Philippines for over a decade, supporting global clients from a local delivery team.',NULL,'So far, Ada has been building skills in software testing, API test automation, debugging, database maintenance, and code review; a full reflection will be completed once the internship concludes.',NULL,NULL,NULL,NULL,NULL,'2026-09-24 22:58:49','2026-09-24 22:58:49');
